import java.util.ArrayList;
import java.util.List;

public class BilleteraDigital extends AbstractIntegracion implements Consultable, Transaccional, Auditable {
    private String proveedorBilletera;
    private List<String> historialEventos;

    public BilleteraDigital(String id, String nombre, String estado, double latencia, String proveedorBilletera) {
        super(id, nombre, estado, latencia);
        this.proveedorBilletera = proveedorBilletera;
        this.historialEventos = new ArrayList<>();
    }

    @Override
    public String mostrarDetalles() {
        return "Billetera Digital [" + identificador + "] - Plataforma: " + proveedorBilletera;
    }

    @Override
    public String consultarEstado() { 
        return estadoConexion; 
    }

    @Override
    public double cotizar(String detalleServicio) { 
        return 25.0; 
    }

    @Override
    public double cotizarMonto(double monto) { 
        return monto * 0.025; // 2.5% de comisión por transacción digital
    }

    @Override
    public boolean cobrar(double monto) {
        registrarEvento("Cobro digital exitoso de: " + monto);
        return true;
    }

    @Override
    public boolean reintegrar(double monto) {
        registrarEvento("Reintegro digital de: " + monto);
        return true;
    }

    @Override
    public void registrarEvento(String evento) { 
        historialEventos.add(evento); 
    }

    @Override
    public List<String> consultarHistorialEventos() { 
        return historialEventos; 
    }
}
